save(472,dict(paragraphs=["Manoranjan Sahoo is an Odia poet from Indupur in Kendrapara, Odisha. His collections include Apadebata, Khalihatare and Kichhi Kabita Kichhi Nirabata. Poems translated by Pitambar Naik in Prachya Review bring his observations of hunger, fear and public life to English readers.","His Kabita Live poem ‘ପବନ’ follows something that ordinarily refuses to stay: the wind. Within a flute, breath meets the touch of lips and fingers and discovers another life as music. The short, descending lines slow that movement, allowing an image of freedom to become one of intimacy and renewal."],sources=[source('Prachya Review — Odia poems by Manoranjan Sahoo','https://prachyareview.com/2023/10/14/odia-poems-by-manoranjan-sahoo-in-english-translation/',['Indupur/Kendrapara origin, three collections and Pitambar Naik translations; poems on hunger and fear.']),source('Google Books — Kichhi Kabita Kichhi Nirabata','https://books.google.com/books/about/Kichhi_Kabita_Kichhi_Nirabata.html?id=3pFvzwEACAAJ',['Black Eagle Books 2022; ISBN 9781645603146; Kendrapara poet identity.'])],books=[dict(title='Kichhi Kabita Kichhi Nirabata',detail='Odia poetry · Black Eagle Books, 2022 · Book record',url='https://books.google.com/books/about/Kichhi_Kabita_Kichhi_Nirabata.html?id=3pFvzwEACAAJ')],identity_match='Name, Odia poetry and Kendrapara locality match supplied biography; journal and book-author record agree on Indupur and bibliography.',poems_read=[dict(id=823,title='ପବନ',basis='Full original read: restless wind arrested/transformed by flute, lips and fingers; rebirth image and short lineation.')],limitations=['No awards imported from book biography without award-source checks.','Romanised collection-title variants recorded by sources; reader uses Prachya spellings except exact catalogue book title.','Poem interpretation does not assign a religious identity to the author.'],next_action='Independent author/editor review of biography and interpretation.'))
